/*
Definition for a Node.
class Node {
    var val: Int
    var neighbors: [Node?]
    init(_ val: Int) {
        self.val = val
        self.neighbors = []
    }
}
*/

class Solution {
    func cloneGraph(_ node: Node?) -> Node? {
        var oldToNew: [ObjectIdentifier: Node] = [:]
        return dfs(node, &oldToNew)
    }

    private func dfs(_ node: Node?, _ oldToNew: inout [ObjectIdentifier: Node]) -> Node? {
        guard let node = node else {
            return nil
        }

        let key = ObjectIdentifier(node)
        if let existing = oldToNew[key] {
            return existing
        }

        let copy = Node(node.val)
        oldToNew[key] = copy

        for nei in node.neighbors {
            copy.neighbors.append(dfs(nei, &oldToNew))
        }

        return copy
    }
}

