use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

impl Solution {
    pub fn clone_graph(node: Option<Rc<RefCell<Node>>>) -> Option<Rc<RefCell<Node>>> {
        let mut old_to_new: HashMap<i32, Rc<RefCell<Node>>> = HashMap::new();
        Self::dfs(node, &mut old_to_new)
    }

    fn dfs(
        node: Option<Rc<RefCell<Node>>>,
        old_to_new: &mut HashMap<i32, Rc<RefCell<Node>>>,
    ) -> Option<Rc<RefCell<Node>>> {
        node.as_ref()?;

        let node_ref = node.as_ref().unwrap();
        let node_val = node_ref.borrow().val;

        if let Some(existing) = old_to_new.get(&node_val) {
            return Some(Rc::clone(existing));
        }

        let copy = Rc::new(RefCell::new(Node::new(node_val)));
        old_to_new.insert(node_val, Rc::clone(&copy));

        for neighbor in &node_ref.borrow().neighbors {
            if let Some(cloned_neighbor) = Self::dfs(Some(Rc::clone(neighbor)), old_to_new) {
                copy.borrow_mut().neighbors.push(cloned_neighbor);
            }
        }

        Some(copy)
    }
}

